const meta = {
  component: Popover,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Open rich content in a portal from a button trigger.

**Import:** `@/registry/erbium/ui/popover`

## Usage

```tsx
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/registry/erbium/ui/popover"
import {{ Button }} from "@/registry/erbium/ui/button"
```

```tsx
<Popover>
  <PopoverTrigger render={<Button variant="outline" />}>Open Popover</PopoverTrigger>
  <PopoverContent>
    <PopoverHeader>
      <PopoverTitle>Title</PopoverTitle>
      <PopoverDescription>Description text here.</PopoverDescription>
    </PopoverHeader>
  </PopoverContent>
</Popover>
```

## Composition

Use the following composition to build a `Popover`:

```text
Popover
├── PopoverTrigger
└── PopoverContent
```

## Interaction ownership

Let the primitive own trigger registration, focus guards, and close animations. Reopening a retained popup or remounting a closed trigger should not require custom transition state. Keep normal unmounting as the default.

The surface provides the shared compact panel gutter. Compose content inside that gutter without adding another padded wrapper. A popover that holds a [Calendar](/docs/components/calendar) tightens its gutter to the calendar's own padding and matches its radius, so a date picker popup reads the same as a standalone calendar.

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Popover](https://base-ui.com/react/components/popover)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Popover>;

export default { ...meta, title: "Components/Popover",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

